import{_ as s,o as t,c as o,a4 as a}from"./chunks/framework.Jm0b7rri.js";const u=JSON.parse('{"title":"xs-troubleshoot(7)","description":"What each fallback notice and common failure means, with the exact text xs prints.","frontmatter":{"title":"xs-troubleshoot(7)","description":"What each fallback notice and common failure means, with the exact text xs prints.","manual":"xs-troubleshoot(7)","manualName":"Troubleshooting","sectionNumber":"7"},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"troubleshooting.md"};function r(l,e,c,i,p,d){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="xs-troubleshoot-7" tabindex="-1">xs-troubleshoot(7) <a class="header-anchor" href="#xs-troubleshoot-7" aria-label="Permalink to &quot;xs-troubleshoot(7)&quot;">​</a></h1><div class="manual-deck"><strong>Troubleshooting</strong><p>What each fallback notice and common failure means, with the exact text xs prints.</p></div><h2 id="fallback" tabindex="-1">FALLBACK NOTICES <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;FALLBACK NOTICES {#fallback}&quot;">​</a></h2><p>When xs cannot do something natively, it runs a real <code>rsync</code> from <code>PATH</code> instead. Before anything is written, it prints one line naming the reason: <code>xs: falling back to rsync: REASON</code>. The transfer still happens, with rsync’s speed, output and behavior. There are three causes, and each one fails in its own way with <code>--no-fallback</code> or <code>XSYNC_FALLBACK=0</code>.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Cause</th><th scope="col">Notice names</th><th scope="col">With <code>--no-fallback</code></th></tr></thead><tbody><tr><td>An option xs does not implement</td><td><code>--backup is not supported by xs</code></td><td>exit 1</td></tr><tr><td>No xs on the remote host</td><td><code>remote xs is not installed on HOST</code></td><td>exit 127</td></tr><tr><td>The remote xs is too old for a requested option</td><td><code>peer does not support …</code></td><td>exit 4</td></tr></tbody></table></div><p>Transfers never fall back once they have started, and malformed protocol data never triggers fallback. <code>--progress=json</code> never falls back either, because rsync cannot produce its events.</p><h3 id="an-option-xs-does-not-implement" tabindex="-1">An option xs does not implement <a class="header-anchor" href="#an-option-xs-does-not-implement" aria-label="Permalink to &quot;An option xs does not implement&quot;">​</a></h3><div class="example-caption">An option xs does not implement runs rsync instead</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --backup</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span>
<span class="line"><span style="color:#DEDEDE;">ls </span><span style="color:#DEDEDE;">dst/notes.txt*</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>dst/notes.txt
dst/notes.txt~</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: falling back to rsync: --backup is not supported by xs</code></pre></div><div class="example-caption">The same request with fallback disabled</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> -a</span><span style="color:#DEDEDE;"> --backup</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 1</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: --backup is not supported by xs (fallback disabled)</code></pre></div><p>The full list is under <a href="options.html#delegated">delegated options</a>. If you need the option and want xs’s speed for everything else, run the two kinds of work as separate commands.</p><h3 id="no-xs-on-the-remote-host" tabindex="-1">No xs on the remote host <a class="header-anchor" href="#no-xs-on-the-remote-host" aria-label="Permalink to &quot;No xs on the remote host&quot;">​</a></h3><div class="example-caption">No xs on the remote host: rsync carries the transfer</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-az</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> host:backup/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 0</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: falling back to rsync: remote xs is not installed on host</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><div class="example-caption">No xs on the remote host, fallback disabled</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> -az</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> host:backup/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 127</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: remote xs is not installed on host (fallback disabled)</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><p>Install the helper with <code>xs --install user@host</code> (see <a href="install.html#remote">remote install</a>), put <code>xs</code> on the remote <code>PATH</code> or in <code>~/.local/bin</code>, or name it with <code>--rsync-path</code>.</p><h3 id="the-remote-xs-is-too-old" tabindex="-1">The remote xs is too old <a class="header-anchor" href="#the-remote-xs-is-too-old" aria-label="Permalink to &quot;The remote xs is too old&quot;">​</a></h3><div class="example-caption">A helper without hard-link support, fallback disabled</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> -aH</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> host:backup/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 4</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: connection unexpectedly closed
xs error: exiting (code 12)
xs: peer does not support hard-link preservation (fallback disabled)</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><div class="example-caption">The same helper with fallback enabled</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aH</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> host:backup/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span>
<span class="line"><span style="color:#DEDEDE;">stat </span><span style="color:#DEDEDE;">-c</span><span style="color:#DEDEDE;"> &quot;%h links  %n&quot;</span><span style="color:#DEDEDE;"> backup/notes.txt</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT · EXIT 0</span><pre><code>exit status: 0
2 links  backup/notes.txt</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: connection unexpectedly closed
xs error: exiting (code 12)
xs: falling back to rsync: peer does not support hard-link preservation</code></pre><p class="example-provenance">Captured through <code>tests/fakessh.sh</code>, an ssh stand-in that runs the remote side on the same machine.</p></div><p>The helper here lacks hard-link support. The two lines before the reason are the helper’s own messages, forwarded over ssh when the client ends the session. They do not mean the transfer broke; the client’s line and its exit status are what count. Update the helper with <code>xs --install user@host</code>, which replaces an older version (only a newer or unrecognized one needs <code>--force</code>), or drop the option. The <a href="protocol.html#features">feature table</a> shows which option needs which feature.</p><h2 id="remote" tabindex="-1">REMOTE CONNECTIONS <a class="header-anchor" href="#remote" aria-label="Permalink to &quot;REMOTE CONNECTIONS {#remote}&quot;">​</a></h2><ul><li><strong>Exit 255</strong> is ssh failing to connect or authenticate; xs passes ssh’s status through. Try the same <code>ssh</code> command by hand. Options for ssh itself go in <code>-e</code>, for example <code>-e &quot;ssh -p 2222 -i ~/.ssh/backup_key&quot;</code>.</li><li><strong>Exit 12</strong> with <code>connection unexpectedly closed (remote shell exited with code N)</code> means the remote shell ended with some other status, for example a login script that exits or prints errors.</li><li><strong>Exit 30</strong> is the <code>--timeout</code> deadline. It counts idle time only, so a slow but moving transfer does not trip it.</li><li><strong>Exit 2</strong> means the two versions are too far apart to talk. Each release speaks its own protocol and the previous one.</li><li>Password and passphrase prompts come from ssh and work as they do with rsync. For unattended runs, use keys or an agent.</li></ul><h2 id="results" tabindex="-1">TRANSFER RESULTS <a class="header-anchor" href="#results" aria-label="Permalink to &quot;TRANSFER RESULTS {#results}&quot;">​</a></h2><h3 id="exit-23-some-files-were-not-transferred" tabindex="-1">Exit 23: some files were not transferred <a class="header-anchor" href="#exit-23-some-files-were-not-transferred" aria-label="Permalink to &quot;Exit 23: some files were not transferred&quot;">​</a></h3><div class="example-caption">A source that does not exist</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> missing/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 23</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: link_stat &quot;missing/&quot; failed: No such file or directory (2)
xs: error summary: 1 error (showing first 1)
  partial transfer (code 23): 1 error
    link_stat &quot;missing/&quot; failed: No such file or directory (2)
xs error: some files/attrs were not transferred (see previous errors) (code 23)</code></pre></div><p>Exit 23 means the run finished but some entries failed, and the error summary lists the first ten. Files that succeeded are in place; nothing is rolled back. Fix the cause and run the same command again, since unchanged files are skipped.</p><h3 id="exit-25-the-deletion-limit" tabindex="-1">Exit 25: the deletion limit <a class="header-anchor" href="#exit-25-the-deletion-limit" aria-label="Permalink to &quot;Exit 25: the deletion limit&quot;">​</a></h3><div class="example-caption">Stop when a mirror would delete too much</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --max-delete=1</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 25</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: Deletions stopped due to --max-delete limit (1)
xs: error summary: 1 error (showing first 1)
  deletion limit (code 25): 1 error
    Deletions stopped due to --max-delete limit (1)
xs error: the --max-delete limit stopped deletions (code 25)</code></pre></div><p><code>--max-delete</code> stopped deletions after the limit; the transfer itself completed. Check with <code>-n</code> first (see <a href="filters.html#mirror">preview a mirror</a>), then raise the limit if the deletions are expected.</p><h3 id="exit-1-a-malformed-value" tabindex="-1">Exit 1: a malformed value <a class="header-anchor" href="#exit-1-a-malformed-value" aria-label="Permalink to &quot;Exit 1: a malformed value&quot;">​</a></h3><div class="example-caption">A malformed value</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">--no-fallback</span><span style="color:#DEDEDE;"> -a</span><span style="color:#DEDEDE;"> --bwlimit=fast</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;">; echo </span><span style="color:#DEDEDE;">&quot;exit status: $?&quot;</span></span></code></pre></div><div class="captured-doc-output example-output"><span class="micro">ACTUAL OUTPUT</span><pre><code>exit status: 1</code></pre><span class="micro stream-label">STDERR</span><pre><code>xs: --bwlimit requires a nonnegative rate: fast
xs error: syntax or usage error (code 1)</code></pre></div><h2 id="progress" tabindex="-1">PROGRESS AND OUTPUT <a class="header-anchor" href="#progress" aria-label="Permalink to &quot;PROGRESS AND OUTPUT {#progress}&quot;">​</a></h2><ul><li><strong>No progress bar in a script.</strong> Progress is on by default only when stderr is a terminal. Use <code>--progress</code>, <code>--info=progress2</code> or <code>--progress=json</code> to get it on a pipe. If a bar appears where it shouldn’t, check <code>XSYNC_OPTS</code>, <code>XSYNC_PROGRESS</code> and the config file (<a href="environment.html#precedence">precedence</a>).</li><li><strong>A push bar that stops below 100%.</strong> On a push, the bar follows what the receiver reports as written, so it waits for the last writes. <code>waiting for receiver</code> means exactly that. Older helpers cannot report writes, so the bar stays at zero until they finish.</li><li><strong>File lines appear all at once.</strong> When stdout is a pipe or file, file lines are sorted and printed at the end, so the output is stable. On a terminal they appear as files finish.</li><li><strong><code>-z</code> on a local copy</strong> is accepted and does nothing: there is no connection to compress.</li></ul><h2 id="macos" tabindex="-1">SURPRISES ON MACOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;SURPRISES ON MACOS {#macos}&quot;">​</a></h2><ul><li><strong>Extra metadata on copies.</strong> On one APFS volume, <code>-a</code> clones files. Clones carry extended attributes, ACLs and access and creation times even without <code>-X</code>, <code>-A</code>, <code>-U</code> or <code>-N</code>, and they share storage with the source until either is modified. Use <code>--no-clone</code> to copy bytes instead.</li><li><strong><code>-E</code> means something else in Apple’s rsync.</strong> Apple’s system rsync uses <code>-E</code> for extended attributes. xs uses <code>-E</code> for executability, as modern rsync does, and <code>-X</code> for attributes. Write <code>--executability</code> when a command may fall back.</li><li><strong>Cloud files.</strong> Files that exist only in iCloud (dataless files) are read normally, which can make the file provider download them.</li></ul><p>Every example on this page is real output, captured from the current binary on Linux. Remote examples ran through an ssh stand-in on one machine. See <a href="exit-status.html">exit status</a> for every code.</p>`,52)])])}const E=s(n,[["render",r]]);export{u as __pageData,E as default};
